CREATE OR REPLACE FUNCTION public.seed_notification_event_configs()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  ON CONFLICT (event_key) DO UPDATE
  SET
    description = EXCLUDED.description,
    title_template = EXCLUDED.title_template,
    message_template = EXCLUDED.message_template,
    email_subject_template = EXCLUDED.email_subject_template,
    email_body_template = EXCLUDED.email_body_template,
    channels = EXCLUDED.channels,
    recipient_rules = EXCLUDED.recipient_rules,
    notification_type = EXCLUDED.notification_type,
    is_active = true,
    updated_at = now();
END;
$$;

SELECT public.seed_notification_event_configs();

DROP FUNCTION public.seed_notification_event_configs();

ON CONFLICT (event_type, channel, COALESCE(regulator_id, '00000000-0000-0000-0000-000000000000'::uuid)) DO UPDATE
SET
  name = EXCLUDED.name,
  subject = EXCLUDED.subject,
  body = EXCLUDED.body,
  variables = EXCLUDED.variables,
  is_active = EXCLUDED.is_active,
  updated_at = now();